#include "okay/Graphics/TtfFont.hpp"
#include "OkfDecode.hpp"        // our own container and decoder (shared/)
#include "RobotoFontOwn.h"      // the launcher's font as OKF1 text (generated by scripts/gen_embedded_fonts.py)

namespace okay {

// The built-in UI font (Roboto Medium) as TrueType bytes. Decoded once; false only if the embedded data were damaged
// (tests/test_embedded_font.cpp pins the decoded bytes, so that cannot ship unnoticed).
bool EmbeddedUIFontData(std::vector<unsigned char>& out) {
    static std::vector<unsigned char> cache;
    static bool tried = false;
    if (!tried) {
        tried = true;
        std::vector<std::uint8_t> bytes;
        if (okf::DecodeLines(okf_data::kRobotoMediumOkf, okf_data::kRobotoMediumOkfLines, bytes)) cache.swap(bytes);
    }
    out = cache;
    return !out.empty();
}

} // namespace okay
